edits.replacement:
#root .ocwin .fbhead{ font-family:inherit; font-weight:600; font-size:18px; letter-spacing:.02em; text-transform:none; }
/* v28.xx (cw-endcard-clean), the critic on the KIA and Abandoned cards (3 and 2 of 5): "the title is too small to lead, the hero beats it", "two stacked 15px grey lines, the XP line competes with the title", "tiles are small, 8px from the hero", "dividers are low contrast", "the Abandoned card has no focal line". Title 40px with 8px under it; the XP line is quiet tx-2; tiles 72px with a 52px picture and 24px above the figure; the stat row rules in the brighter line; the Abandoned loot line is its own 24px bone line with 24px around it. Words unchanged. */
#root .outcome h1{ font-size:40px; font-weight:700; margin-bottom:8px; }
#root #oc_manifest span[style*="var(--amber)"]{ color:var(--tx-2) !important; }
#root .octile{ width:72px; height:72px; }
#root .octile img{ width:52px !important; height:52px !important; }
#root .octiles{ margin:24px 0 8px; }
#root .ocloss{ margin:24px 0 32px; }
#root .ocstat{ border-top-color:var(--ui-line-hi); border-bottom-color:var(--ui-line-hi); }
#root .ocnote{ display:block; margin:24px 0; font-family:var(--f-cond); font-size:24px; font-weight:700; line-height:1.2; color:var(--tx-1); }

check:
{v:'VER',what:'the end cards lead with a 40px title, 72px loss tiles and the Abandoned loot line is its own 24px line (critic: title too small, tiles small, no focal line; screens 35 and 60)',
 run:function(){
   if(!(window.__deploy&&window.__state&&window.__endRaid)) return 'SKIP: cannot deploy and end a raid here';
   var man=document.getElementById('oc_manifest'), oc=document.getElementById('outcome');
   if(!man||!oc) return 'SKIP: no outcome card in the page';
   var bad=[], g, h1, tmp, wrap, nt, fs;
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||!g.player||!g.bag) return 'SKIP: no live raid bag';
     g.t=60; try{ g.tel.shots=3; }catch(_s){}
     man.innerHTML='';
     __endRaid('abandon');
     if(g.over!=='abandon'||!oc.classList.contains('on')) return 'SKIP: the abandon card was not drawn here';
     h1=document.getElementById('oc_title')||oc.querySelector('h1');
     if(h1&&Math.abs(parseFloat(getComputedStyle(h1).fontSize)-40)>1.5) bad.push('the card title is '+getComputedStyle(h1).fontSize+', not 40px');
     nt=man.querySelector('.ocnote');
     if(!nt) bad.push('the Abandoned loot line is not its own line');
     else{
       fs=parseFloat(getComputedStyle(nt).fontSize);
       if(Math.abs(fs-24)>1.5) bad.push('the loot line is '+fs+'px, not 24');
       if(String(nt.textContent).indexOf('Run abandoned.')!==0||String(nt.textContent).indexOf('left behind.')<0) bad.push('the loot line words changed: '+nt.textContent);
     }
     wrap=document.createElement('div'); wrap.className='octiles'; tmp=document.createElement('div'); tmp.className='octile'; wrap.appendChild(tmp); man.appendChild(wrap);
     if(Math.abs(tmp.offsetWidth-72)>1.5) bad.push('a loss tile is '+tmp.offsetWidth+'px, not 72');
     man.removeChild(wrap);
     return bad.length?bad.join('; '):null;
   } finally {
     try{ if(g&&!g.over){ g.player.downed=false; __endRaid('abandon'); } }catch(_f){}
     try{ man.innerHTML=''; oc.classList.remove('on'); }catch(_g){}
   }
 }},
